import{at as e,it as t,n,vt as r}from"./chunks/framework.CinQa4et.js";var i=JSON.parse(`{"title":"トラブルシューティング","description":"","frontmatter":{},"headers":[],"relativePath":"troubleshooting.md","filePath":"troubleshooting.md","lastUpdated":1793464466000}`),a={name:`troubleshooting.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="トラブルシューティング" tabindex="-1">トラブルシューティング <a class="header-anchor" href="#トラブルシューティング" aria-label="Permalink to “トラブルシューティング”">​</a></h1><h2 id="最初に確認する順番" tabindex="-1">最初に確認する順番 <a class="header-anchor" href="#最初に確認する順番" aria-label="Permalink to “最初に確認する順番”">​</a></h2><p><a href="./integration/sdk">同意とタグ</a> → <a href="./guides/sites">サイト設定</a> → <a href="./guides/campaigns">施策の状態</a> → <a href="./guides/debugging">診断パネル</a>の順に確認すると、どこまで処理できているか分かります。</p><table tabindex="0"><thead><tr><th>症状</th><th>確認すること</th></tr></thead><tbody><tr><td>タグを入れても通信しない</td><td>SDK読込、同意、サイトID、HTTPS、メタデータ送信、CSP</td></tr><tr><td>ページを開いてすぐオファーが出ない</td><td>初期判断は行うが、有効閲覧数・時間や条件不足なら出さない</td></tr><tr><td>JSONは返るが表示しない</td><td>decision、campaign、表示形式、画像読込、独自コードのreportShown、CSP</td></tr><tr><td>一度閉じたあと出ない</td><td>ブラウザ内のdismissedと表示上限</td></tr><tr><td>設定を保存できない</td><td>権限、入力上限、古いrevision、必要なパスキー再認証</td></tr><tr><td>プレビューが拒否される</td><td>Origin・許可/除外経路・施策対象・表示タイトル・期限</td></tr><tr><td>別サイトが一覧にない</td><td>アカウントのサイト所属</td></tr></tbody></table><h2 id="パスキーでログインできない" tabindex="-1">パスキーでログインできない <a class="header-anchor" href="#パスキーでログインできない" aria-label="Permalink to “パスキーでログインできない”">​</a></h2><p>メールとパスキーのアカウントを確認します。正しいHTTPS Originで開き、別の登録済み端末やキーも試してください。localhostとIPは同じRPではありません。</p><p>端末を失った場合は<a href="./guides/accounts#端末を失った場合">復旧手順</a>を使います。メールだけで新しい管理者を登録する公開の復旧APIはありません。</p><h2 id="accessで入場できない" tabindex="-1">Accessで入場できない <a class="header-anchor" href="#accessで入場できない" aria-label="Permalink to “Accessで入場できない”">​</a></h2><p>許可されたメールを使ってください。メールコードが届かない場合は入力、迷惑メール、期限を確認し、必要なら自分で再送します。JevSenseの招待だけではAccessの許可対象は増えません。</p><p>入場後もJSONの403が出る場合は、Accessのaudience・発行元・固定AUTH_ORIGINが一致しているか運用者が確認します。個別Deployment URLではなく、固定Preview URLを使います。</p><h2 id="cloudflareの認証エラー" tabindex="-1">Cloudflareの認証エラー <a class="header-anchor" href="#cloudflareの認証エラー" aria-label="Permalink to “Cloudflareの認証エラー”">​</a></h2><p>CLOUDFLARE_API_TOKENとJEV_API_KEYは別です。Tokenの対象アカウントと操作権限を確認します。Secretの「ready」は実APIの許可を保証しません。</p><p>アカウント用API Tokenは、ユーザー用の<code>/user/tokens/verify</code>だけでは検証できません。<code>wrangler whoami</code>またはアカウント用検証APIを使い、401だけで再入力を繰り返さないでください。</p><p>Accessアプリを作れない403ではAccess編集権限、D1操作の403ではD1編集権限とDBの接続先を確認します。</p><h2 id="モデルや費用のエラー" tabindex="-1">モデルや費用のエラー <a class="header-anchor" href="#モデルや費用のエラー" aria-label="Permalink to “モデルや費用のエラー”">​</a></h2><table tabindex="0"><thead><tr><th>理由</th><th>対応</th></tr></thead><tbody><tr><td>model_not_configured</td><td>実行時SecretのJEV_API_KEYを確認</td></tr><tr><td>model_error / 502</td><td>キー、利用できるモデル名、提供元の稼働と応答を確認</td></tr><tr><td>budget_exhausted</td><td>UTC日単位の費用枠を確認</td></tr><tr><td>busy</td><td>同時実行上限を確認</td></tr><tr><td>rate_limited / 429</td><td>操作や要求が集中していないか確認し、時間を置く</td></tr></tbody></table><p>Previewの固定スタブは実モデルの障害確認には使えません。キーを修正するときも、値をログやIssuesへ貼らないでください。</p><h2 id="本番リリースが停止する" tabindex="-1">本番リリースが停止する <a class="header-anchor" href="#本番リリースが停止する" aria-label="Permalink to “本番リリースが停止する”">​</a></h2><p>40文字の確認済みコミット、現在のHEAD、未保存の変更、<code>data/deployments/preview.json</code>の配備記録を確認します。記録がない場合はPreviewを作り直します。本番へ強制配備してこの確認を迂回しないでください。</p><h2 id="それでも解決しない場合" tabindex="-1">それでも解決しない場合 <a class="header-anchor" href="#それでも解決しない場合" aria-label="Permalink to “それでも解決しない場合”">​</a></h2><p><a href="https://github.com/manji6/jev-personalization/issues" target="_blank" rel="noreferrer">Issues</a>に、再現手順、ブラウザ/OS、起きた操作、期待した結果、秘密情報を除いたエラー名を添えてください。Cookie・キー・トークン・フォーム値・実閲覧履歴は共有しないでください。</p>`,21)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};